 function motion(){const moving=typeof watch!=='undefined'&&watch!==null&&typeof isDemo!=='undefined'&&!isDemo&&typeof lastSpeedMps!=='undefined'&&lastSpeedMps>1.4&&typeof gpsTime!=='undefined'&&Date.now()-gpsTime<15000&&typeof lastAccuracyMeters!=='undefined'&&lastAccuracyMeters<=35;const input=document.getElementById('query');input.readOnly=!!moving;input.setAttribute('aria-description',moving?'Use voice, saved destinations or map selection while moving.':'Type an address while parked.');}
 motion();setInterval(motion,1000);
 const details=document.createElement('details');details.className='destination-saved-shortcuts';const heading=document.createElement('summary');heading.textContent='Saved destinations · one tap';const list=document.createElement('div');list.className='nav-saved-shortcuts';details.append(heading,list);row.after(details);
 function render(){list.replaceChildren();for(const item of typeof savedPlaces!=='undefined'?savedPlaces:[]){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=item.label;b.onclick=()=>{if(typeof watch!=='undefined'&&watch!==null&&!confirm('Change the destination and recalculate your active route?'))return;setSearchedDestination(item.place,true);};list.append(b);}details.hidden=!list.children.length;}
 function translate(){const words=({fa:['گفتن مقصد','چسباندن آدرس / لینک نقشه','مقصدهای ذخیره‌شده · یک لمس'],fr:['Dicter la destination','Coller une adresse / un lien','Destinations enregistrées'],hi:['गंतव्य बोलें','पता / नक्शा लिंक पेस्ट करें','सहेजे गए गंतव्य'],es:['Decir destino','Pegar dirección / enlace','Destinos guardados'],de:['Ziel sprechen','Adresse / Kartenlink einfügen','Gespeicherte Ziele']})[document.documentElement.lang]||['Speak destination','Paste address / map link','Saved destinations · one tap'];voice.querySelector('span').textContent=words[0];paste.textContent=words[1];heading.textContent=words[2];}translate();new MutationObserver(translate).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});
 render();const picker=document.getElementById('saved-places');if(picker)new MutationObserver(render).observe(picker,{childList:true});
